contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: set MinSum, deposit some Ether via Put, advance nothing (timestamp can't be changed here),
    // so to allow Collect to succeed we rely on _lockTime = 0 when putting so unlockTime is <= now.
    // The property: if Collect call does NOT revert and before balance >= MinSum and block.timestamp>unlockTime,
    // then after the call the holder.balance decreased by _am and address(c).balance decreased by _am.

    function run(uint minSum, uint putLockTime, uint depositAmount, uint collectAmount, address payable beneficiary) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");
        // initialize MinSum (only allowed before Initialized); call SetMinSum
        c.SetMinSum(minSum);
        // Ensure LogFile is set to some existing address — use address(c) itself (any address is allowed)
        c.SetLogFile(address(c));
        // Do not call Initialized() so SetMinSum/SetLogFile were allowed.

        // Prepare: record before-values for the caller (this test contract) as seen by c.
        // c.Acc is public mapping; getter signature is Acc(address) returns (uint,uint)
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Make a deposit via Put: must send Ether equal to depositAmount.
        c.Put{value: depositAmount}(putLockTime);

        // Read values after deposit, before Collect
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Sanity: the deposit must have increased contract balance by depositAmount and holder balance by depositAmount
        // (we won't assert that here because it's not the property; but rely on midBal)

        // Attempt Collect and observe whether it reverts.
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General property to assert:
        // If Collect did not revert AND before calling Collect the holder balance was >= minSum AND >= collectAmount
        // AND block.timestamp > unlockTime held just before Collect, then the holder balance must have decreased by collectAmount
        // and the contract's Ether balance must have decreased by collectAmount as well.
        // We observe the necessary preconditions using midBal and midUnlock (values immediately before Collect).

        // Construct the boolean property expression for the assert.
        bool preconds = (!reverted) ? true : false; // start with reverted flag: we'll include detailed preconditions below

        // Build condition that Collect should have been allowed (according to contract logic):
        // allowedIf = (midBal >= minSum) && (midBal >= collectAmount) && (block.timestamp > midUnlock)
        bool allowedIf = (midBal >= minSum) && (midBal >= collectAmount) && (block.timestamp > midUnlock);

        // If allowedIf and call did not revert, then balances decreased by exactly collectAmount.
        // Otherwise we don't require anything. So final assert: !(allowedIf && !reverted) || (afterBal + collectAmount == midBal && afterContractBal + collectAmount == midContractBal)
        assert( (!allowedIf || !reverted) || (afterBal + collectAmount == midBal && afterContractBal + collectAmount == midContractBal) );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We keep the test simple: set MinSum to 0, set a LogFile, deposit funds with lockTime = 0, then call Collect.
    // Parameters: depositAmount must be >= collectAmount and > 0. The function is payable and must be funded by the caller.
    function run(uint depositAmount, uint collectAmount) public payable {
        require(depositAmount >= collectAmount, "deposit must cover collect");
        require(depositAmount > 0, "deposit > 0");
        require(address(this).balance >= depositAmount, "test contract lacks ETH");

        // Initialize contract so SetMinSum / SetLogFile can be called
        c.SetMinSum(0);
        c.SetLogFile(address(c));
        // Do NOT call Initialized() so settings are allowed earlier.

        // Read balance before deposit
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));

        // Deposit Ether with lockTime = 0 so unlockTime <= now
        c.Put{value: depositAmount}(0);

        // Read balance immediately after deposit
        (uint midUnlock, uint midBal) = c.Acc(address(this));

        // Attempt Collect and record whether it reverted
        bool didRevert;
        try c.Collect(collectAmount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Read balance after Collect attempt
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        // Assert the general rule: if Collect did not revert, then the holder balance decreased by exactly collectAmount.
        assert(didRevert || (afterBal + collectAmount == midBal));
    }

    receive() external payable { }
}

