contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes lockTime and amount to send to Put (or fallback if useFallback=true)
    function run(uint lockTime, uint amount, bool useFallback) public payable {
        require(address(this).balance >= amount);

        // read balances before
        (uint beforeAccBalance, ) = (_getAccBalance(), 0);
        uint beforeCbalance = address(c).balance;

        bool reverted;
        if(useFallback) {
            // call fallback by sending Ether with empty data
            try c.call{value: amount}("") {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.Put{value: amount}(lockTime) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterAccBalance = _getAccBalance();
        uint afterCbalance = address(c).balance;

        // If call succeeded, then the account balance stored in c.Acc for this contract's address
        // must have increased by exactly amount and contract C's ETH balance increased by amount.
        assert( reverted || (afterAccBalance == beforeAccBalance + amount && afterCbalance == beforeCbalance + amount) );
    }

    // helper to read Acc[msg.sender].balance for this test contract's address
    function _getAccBalance() internal returns (uint) {
        // C.Acc is a public mapping returning (uint unlockTime, uint balance) struct components via the autogenerated getter.
        // The getter for mapping (address => Holder) public Acc returns (uint unlockTime, uint balance).
        (uint unlockTime, uint bal) = c.Acc(address(this));
        // silence unused variable warning
        unlockTime;
        return bal;
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call Put(lockTime) or trigger fallback by sending Ether with empty data.
    // amount is the Ether sent to C; require this contract has enough balance.
    function run(uint lockTime, uint amount, bool useFallback) public payable {
        require(address(this).balance >= amount);

        // read balances before via public getters
        (, uint beforeAccBal) = c.Acc(address(this));
        uint beforeCbal = address(c).balance;

        bool reverted;
        // perform the state-changing call as a top-level statement
        if (useFallback) {
            // trigger fallback by sending empty calldata to c
            (bool ok, ) = address(c).call{value: amount}(""");
            reverted = !ok;
        } else {
            try c.Put{value: amount}(lockTime) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read balances after
        (, uint afterAccBal) = c.Acc(address(this));
        uint afterCbal = address(c).balance;

        // General rule: if call reverted, balances unchanged; else both balances increased exactly by amount
        assert(
            reverted
            ? (afterAccBal == beforeAccBal && afterCbal == beforeCbal)
            : (afterAccBal == beforeAccBal + amount && afterCbal == beforeCbal + amount)
        );
    }

    receive() external payable {}
}

