contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call sequence: ensure some recorded balance >= MinSum and unlocked, then try Collect(am).
    // Parameters: initialDeposit funds the contract will send to c via Put, lockTime to set unlockTime,
    // am is the amount to Collect. The test contract must hold initialDeposit wei.
    function run(uint lockTime, uint initialDeposit, uint am) public payable {
        require(address(this).balance >= initialDeposit);

        // ensure MinSum is small so condition acc.balance >= MinSum can hold; set it if contract not initialized
        // SetMinSum may revert if Initialized already called; so try/catch not allowed for state-changing call inside expressions
        // We call SetMinSum as a top-level statement. If it reverts, that's fine for the test — we proceed.
        // But per constraints, every state-changing call must be top-level. We'll attempt SetMinSum and ignore revert via try/catch.
        try c.SetMinSum(0) {
        } catch {}

        // Record before observed values
        (uint beforeUnlock, uint beforeAccBal) = c.Acc(address(this));
        uint beforeThisBal = address(this).balance;
        uint beforeCbal = address(c).balance;

        // Send initialDeposit to C via Put to create recorded balance (may revert). Must be top-level.
        bool putReverted;
        try c.Put{value: initialDeposit}(lockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // After attempting Put, read recorded balance and C balance
        (, uint midAccBal) = c.Acc(address(this));
        uint midCbal = address(c).balance;

        // Now attempt Collect(am) (top-level). Catch whether it reverted.
        bool collectReverted;
        try c.Collect(am) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe after values
        (, uint afterAccBal) = c.Acc(address(this));
        uint afterThisBal = address(this).balance;
        uint afterCbal = address(c).balance;

        // Formulate the invariant:
        // If Collect succeeded (did not revert) then recorded balance decreased by am and this contract's balance increased by am and C's balance decreased by am.
        // Otherwise (Collect reverted or had no effect) the recorded balance and balances did not increase relative to mid values in a way that would indicate successful transfer to this contract.
        // We avoid underflow by expressing decreases using equality where appropriate.
        assert(
            collectReverted
            ? (
                // If collect reverted, nothing was transferred out to this contract: afterThisBal == midThisBal and afterAccBal == midAccBal and afterCbal == midCbal
                // We don't have midThisBal variable; midThisBal == beforeThisBal - initialDeposit if Put succeeded, or beforeThisBal otherwise.
                // But easier: require that if Collect reverted then this contract's balance did not increase compared to before Collect attempt (afterThisBal <= beforeThisBal + (putReverted ? 0 : 0))
                // Simpler safe check: when collectReverted, ensure recorded balance did not decrease by am and this contract's balance did not increase by am.
                !(afterAccBal + am == midAccBal && afterThisBal == (beforeThisBal + am))
              )
            : (
                // If Collect succeeded, then recorded balance decreased exactly by am and this contract gained am and contract C lost am.
                afterAccBal + am == midAccBal
                && afterThisBal == (beforeThisBal + am)
                && afterCbal + am == midCbal
              )
        );
    }

    receive() external payable {}
}
